fn id(value: u8) -> ObjectId {
    ObjectId::new([value; 16])
}

fn string(value: &str) -> CanonicalValue {
    CanonicalValue::new(OvbRaw::Text(value.to_owned())).unwrap()
}

fn integer(value: i64) -> CanonicalValue {
    CanonicalValue::new(OvbRaw::Int(value.into())).unwrap()
}

fn schema(explicit_key: bool, name_type: FieldType) -> Schema {
    Schema {
        version: orna_evolution_v1::EvolutionVersion::V1_0,
        tables: vec![Table {
            id: id(1),
            name: "Contact".into(),
            explicit_key,
            fields: vec![
                Field { id: id(4), name: "id".into(), ty: FieldType::Int, role: FieldRole::Key, optional: false, introduction_fallback: None },
                Field { id: id(2), name: "name".into(), ty: name_type, role: FieldRole::Stored, optional: false, introduction_fallback: None },
                Field { id: id(3), name: "city".into(), ty: FieldType::Str, role: FieldRole::Stored, optional: false, introduction_fallback: None },
            ],
        }],
    }
}

fn string_key_schema() -> Schema {
    let mut schema = schema(true, FieldType::Str);
    schema.tables[0].fields[0].ty = FieldType::Str;
    schema
}

fn rekey_row(row: &KeyedRow, key: &str) -> KeyedRow {
    let mut row = row.clone();
    row.key = string(key);
    row
}

fn edit_name(row: &KeyedRow, value: &str) -> KeyedRow {
    let mut row = row.clone();
    row.fields.insert(id(2), string(value));
    row
}

fn parse_fixture(source: &str, kind: RowKeyKind) -> KeyedRow {
    let parsed = parse_row(source);
    assert!(parsed.diagnostics.is_empty(), "{:#?}", parsed.diagnostics);
    let Expr::Record { fields, .. } = parsed.value else { panic!("record fixture") };
    let mut key = None;
    let mut values = BTreeMap::new();
    for field in fields {
        let Expr::Literal { text, kind: literal_kind, .. } = field.value else { panic!("literal fixture") };
        match field.name.as_str() {
            "id" => {
                key = Some(match literal_kind {
                    LiteralKind::Integer => {
                        let number: i64 = text.parse().unwrap();
                        CanonicalValue::new(OvbRaw::Int(number.into())).unwrap()
                    }
                    LiteralKind::String => {
                        let value = text.strip_prefix('"').unwrap().strip_suffix('"').unwrap();
                        string(value)
                    }
                    other => panic!("unexpected key literal {other:?}"),
                });
            }
            "name" | "city" => {
                assert_eq!(literal_kind, LiteralKind::String);
                let value = text.strip_prefix('"').unwrap().strip_suffix('"').unwrap();
                let field_id = if field.name == "name" { id(2) } else { id(3) };
                values.insert(field_id, string(value));
            }
            other => panic!("unexpected fixture field {other}"),
        }
    }
    KeyedRow { table: id(1), key: key.unwrap(), key_kind: kind, fields: values }
}

fn parse_checkpoint_fixture(source: &str) -> CheckpointGeneration {
    let parsed = parse_row(source);
    assert!(parsed.diagnostics.is_empty(), "{:#?}", parsed.diagnostics);
    let Expr::Record { fields, .. } = parsed.value else { panic!("checkpoint fixture must be a record") };
    let mut generation = None;
    let mut position = None;
    for field in fields {
        let Expr::Literal { text, kind, .. } = field.value else { panic!("checkpoint fields must be literals") };
        match field.name.as_str() {
            "generation" => {
                assert_eq!(kind, LiteralKind::Integer);
                generation = Some(text.parse::<u64>().unwrap());
            }
            "position" => {
                assert_eq!(kind, LiteralKind::String);
                position = Some(
                    text.strip_prefix('\"').unwrap().strip_suffix('\"').unwrap().as_bytes().to_vec(),
                );
            }
            other => panic!("unexpected checkpoint fixture field {other}"),
        }
    }
    CheckpointGeneration { generation: generation.expect("fixture generation"), position }
}

fn manifest(digest: u8, segment_digest: u8, locator: &[u8]) -> TableManifest {
    TableManifest {
        digest: [digest; 32],
        segments: vec![RowSegmentManifest { locator: locator.to_vec(), range: KeyRange::all(), digest: [segment_digest; 32] }],
    }
}

fn depth_split_manifest(digest: u8, segment_digests: [u8; 3], locators: [&[u8]; 3]) -> TableManifest {
    let middle = string("root/child").encode().unwrap();
    let deep = string("root/child/deep").encode().unwrap();
    let ranges = [
        KeyRange::new(None, Some(middle.clone())).unwrap(),
        KeyRange::new(Some(middle), Some(deep.clone())).unwrap(),
        KeyRange::new(Some(deep), None).unwrap(),
    ];
    let segments = ranges
        .into_iter()
        .zip(segment_digests)
        .zip(locators)
        .map(|((range, segment_digest), locator)| RowSegmentManifest {
            locator: locator.to_vec(),
            range,
            digest: [segment_digest; 32],
        })
        .collect();
    TableManifest { digest: [digest; 32], segments }
}

fn snapshot(schema: Schema, manifest: TableManifest, checkpoint: Option<CheckpointGeneration>) -> ThreeWaySnapshot {
    let mut tables = BTreeMap::new();
    tables.insert(id(1), manifest);
    let mut checkpoints = BTreeMap::new();
    if let Some(checkpoint) = checkpoint { checkpoints.insert(b"consumer/source".to_vec(), checkpoint); }
    ThreeWaySnapshot { schema, tables, checkpoints }
}

fn paired_depth_schema() -> Schema {
    let mut schema = string_key_schema();
    let mut paired_table = schema.tables[0].clone();
    paired_table.id = id(2);
    paired_table.name = "PairedContact".into();
    schema.tables.push(paired_table);
    schema
}

fn paired_depth_recovery_inputs(
    reverse_rows: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let middle = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let mut paired_shallow = shallow.clone();
    paired_shallow.table = id(2);
    let mut paired_middle = middle.clone();
    paired_middle.table = id(2);
    let mut paired_deep = deep.clone();
    paired_deep.table = id(2);

    let mut source = FixtureRows::default();
    source.add(
        MergeSide::Base,
        b"pair-a-base-root",
        vec![shallow.clone()],
    );
    source.add(
        MergeSide::Base,
        b"pair-a-base-middle",
        vec![middle.clone()],
    );
    source.add(MergeSide::Base, b"pair-a-base-deep", vec![deep.clone()]);
    source.add(MergeSide::Left, b"pair-a-left-root", Vec::new());
    source.add(MergeSide::Left, b"pair-a-left-middle", vec![middle]);
    source.add(MergeSide::Left, b"pair-a-left-deep", Vec::new());
    source.add(MergeSide::Right, b"pair-a-right-root", Vec::new());
    source.add(MergeSide::Right, b"pair-a-right-middle", Vec::new());
    source.add(MergeSide::Right, b"pair-a-right-deep", vec![deep]);

    source.add(
        MergeSide::Base,
        b"pair-b-base-root",
        vec![paired_shallow.clone()],
    );
    source.add(
        MergeSide::Base,
        b"pair-b-base-middle",
        vec![paired_middle.clone()],
    );
    source.add(
        MergeSide::Base,
        b"pair-b-base-deep",
        vec![paired_deep.clone()],
    );
    source.add(MergeSide::Left, b"pair-b-left-root", Vec::new());
    source.add(
        MergeSide::Left,
        b"pair-b-left-middle",
        vec![paired_middle.clone()],
    );
    source.add(
        MergeSide::Left,
        b"pair-b-left-deep",
        vec![paired_deep],
    );
    source.add(MergeSide::Right, b"pair-b-right-root", Vec::new());
    source.add(
        MergeSide::Right,
        b"pair-b-right-middle",
        vec![paired_middle],
    );
    source.add(MergeSide::Right, b"pair-b-right-deep", Vec::new());

    if reverse_rows {
        for rows in source.rows.values_mut() {
            rows.reverse();
        }
    }

    let schema = paired_depth_schema();
    let make_snapshot = |first, second| {
        let mut tables = BTreeMap::new();
        tables.insert(id(1), first);
        tables.insert(id(2), second);
        ThreeWaySnapshot { schema: schema.clone(), tables, checkpoints: BTreeMap::new() }
    };
    let base = make_snapshot(
        depth_split_manifest(
            41,
            [41, 42, 43],
            [b"pair-a-base-root", b"pair-a-base-middle", b"pair-a-base-deep"],
        ),
        depth_split_manifest(
            51,
            [51, 52, 53],
            [b"pair-b-base-root", b"pair-b-base-middle", b"pair-b-base-deep"],
        ),
    );
    let left = make_snapshot(
        depth_split_manifest(
            61,
            [61, 62, 63],
            [b"pair-a-left-root", b"pair-a-left-middle", b"pair-a-left-deep"],
        ),
        depth_split_manifest(
            71,
            [71, 72, 73],
            [b"pair-b-left-root", b"pair-b-left-middle", b"pair-b-left-deep"],
        ),
    );
    let right = make_snapshot(
        depth_split_manifest(
            81,
            [81, 82, 83],
            [b"pair-a-right-root", b"pair-a-right-middle", b"pair-a-right-deep"],
        ),
        depth_split_manifest(
            91,
            [91, 92, 93],
            [b"pair-b-right-root", b"pair-b-right-middle", b"pair-b-right-deep"],
        ),
    );
    (base, left, right, source)
}

#[derive(Default)]
struct FixtureRows {
    rows: BTreeMap<(MergeSide, Vec<u8>), Vec<KeyedRow>>,
    visited: Vec<(MergeSide, Vec<u8>)>,
}

impl FixtureRows {
    fn add(&mut self, side: MergeSide, locator: &[u8], rows: Vec<KeyedRow>) {
        self.rows.insert((side, locator.to_vec()), rows);
    }
}

impl BranchRowSource for FixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        let locator = segment.map(|segment| segment.locator.clone()).unwrap_or_default();
        self.visited.push((side, locator.clone()));
        for row in self.rows.get(&(side, locator)).into_iter().flatten() {
            assert_eq!(row.table, table);
            let key = row.key.encode().map_err(|error| error.to_string())?;
            if range.contains(&key) && !visitor(row.clone()) {
                break;
            }
        }
        Ok(())
    }
}

struct BarrierFixtureRows {
    source: FixtureRows,
    first_load: Option<Arc<Barrier>>,
}

impl BranchRowSource for BarrierFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        if let Some(first_load) = self.first_load.take() {
            first_load.wait();
        }
        self.source.visit_rows(side, table, segment, range, visitor)
    }
}

struct RecoveringFixtureRows {
    source: FixtureRows,
    fail_first_load: bool,
}

impl BranchRowSource for RecoveringFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        if self.fail_first_load {
            self.fail_first_load = false;
            return Err("fixture row source stopped at recovery boundary".into());
        }
        self.source.visit_rows(side, table, segment, range, visitor)
    }
}

struct PartialRecoveringFixtureRows {
    source: FixtureRows,
    fail_after_rows: Option<usize>,
    rows_delivered_before_failure: usize,
}

impl BranchRowSource for PartialRecoveringFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        if let Some(limit) = self.fail_after_rows.take() {
            let mut delivered = 0;
            let mut partial_visitor = |row| {
                if delivered == limit {
                    return false;
                }
                delivered += 1;
                visitor(row)
            };
            self.source
                .visit_rows(side, table, segment, range, &mut partial_visitor)?;
            self.rows_delivered_before_failure = delivered;
            return Err("fixture row source failed after partial storm delivery".into());
        }
        self.source.visit_rows(side, table, segment, range, visitor)
    }
}

struct FailAfterRowsFixtureRows {
    source: FixtureRows,
    fail_after_rows: usize,
    rows_delivered: usize,
    failed_at: Option<(ObjectId, MergeSide, Vec<u8>)>,
}

impl BranchRowSource for FailAfterRowsFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        let locator = segment.map(|segment| segment.locator.clone()).unwrap_or_default();
        let mut delivered = self.rows_delivered;
        let fail_after_rows = self.fail_after_rows;
        let mut stopped_at_failure = false;
        self.source.visit_rows(side, table, segment, range, &mut |row| {
            if delivered == fail_after_rows {
                stopped_at_failure = true;
                return false;
            }
            delivered += 1;
            visitor(row)
        })?;
        self.rows_delivered = delivered;
        if stopped_at_failure {
            self.failed_at = Some((table, side, locator));
            return Err("fixture row source failed after a partial row prefix".into());
        }
        Ok(())
    }
}

struct FailOnTableAfterRowsFixtureRows {
    source: FixtureRows,
    table: ObjectId,
    side: MergeSide,
    fail_after_rows: usize,
    rows_delivered: usize,
    rows_seen: Vec<CanonicalValue>,
    failed_at: Option<(ObjectId, MergeSide, Vec<u8>)>,
}

impl BranchRowSource for FailOnTableAfterRowsFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        if table != self.table || side != self.side {
            return self.source.visit_rows(side, table, segment, range, visitor);
        }

        let locator = segment.map(|segment| segment.locator.clone()).unwrap_or_default();
        let mut delivered = self.rows_delivered;
        let mut rows_seen = Vec::new();
        let mut stopped_at_failure = false;
        self.source.visit_rows(side, table, segment, range, &mut |row| {
            if delivered == self.fail_after_rows {
                stopped_at_failure = true;
                return false;
            }
            delivered += 1;
            rows_seen.push(row.key.clone());
            visitor(row)
        })?;
        self.rows_delivered = delivered;
        self.rows_seen.extend(rows_seen);
        if stopped_at_failure {
            self.failed_at = Some((table, side, locator));
            return Err("fixture row source failed after a partial row prefix".into());
        }
        Ok(())
    }
}

struct BarrierFailOnTableAfterRowsFixtureRows {
    source: FailOnTableAfterRowsFixtureRows,
    first_load: Option<Arc<Barrier>>,
}

impl BranchRowSource for BarrierFailOnTableAfterRowsFixtureRows {
    fn visit_rows(
        &mut self,
        side: MergeSide,
        table: ObjectId,
        segment: Option<&RowSegmentManifest>,
        range: &KeyRange,
        visitor: &mut dyn FnMut(KeyedRow) -> bool,
    ) -> Result<(), String> {
        if let Some(first_load) = self.first_load.take() {
            first_load.wait();
        }
        self.source.visit_rows(side, table, segment, range, visitor)
    }
}

fn budget() -> BranchMergeBudget {
    BranchMergeBudget { max_rows_examined: 100, max_conflicts: 20 }
}

fn row_checkpoint_conflict_inputs() -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let base_checkpoint = CheckpointGeneration {
        generation: 4,
        position: Some(b"base-token".to_vec()),
    };
    let left_checkpoint = CheckpointGeneration {
        generation: 5,
        position: Some(b"left-token".to_vec()),
    };
    let right_checkpoint = CheckpointGeneration {
        generation: 6,
        position: Some(b"right-token".to_vec()),
    };
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"base", vec![parse_fixture(BASE, RowKeyKind::Explicit)]);
    source.add(MergeSide::Left, b"left", vec![parse_fixture(LEFT, RowKeyKind::Explicit)]);
    source.add(MergeSide::Right, b"right", vec![parse_fixture(CONFLICT, RowKeyKind::Explicit)]);
    let base = snapshot(
        schema(true, FieldType::Str),
        manifest(1, 1, b"base"),
        Some(base_checkpoint),
    );
    let left = snapshot(
        schema(true, FieldType::Str),
        manifest(2, 2, b"left"),
        Some(left_checkpoint),
    );
    let right = snapshot(
        schema(true, FieldType::Str),
        manifest(3, 3, b"right"),
        Some(right_checkpoint),
    );
    (base, left, right, source)
}

fn schema_conflict_inputs() -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let base_schema = schema(true, FieldType::Str);
    let mut left_schema = base_schema.clone();
    left_schema.tables[0].fields[1].ty = FieldType::Int;
    left_schema.tables[0].fields[2].ty = FieldType::Int;
    let mut right_schema = base_schema.clone();
    right_schema.tables[0].fields[1].ty = FieldType::Bool;
    right_schema.tables[0].fields[2].ty = FieldType::Bool;
    let base_checkpoint = CheckpointGeneration {
        generation: 4,
        position: Some(b"base-token".to_vec()),
    };
    let left_checkpoint = CheckpointGeneration {
        generation: 5,
        position: Some(b"left-token".to_vec()),
    };
    let right_checkpoint = CheckpointGeneration {
        generation: 6,
        position: Some(b"right-token".to_vec()),
    };
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"base", vec![parse_fixture(BASE, RowKeyKind::Explicit)]);
    source.add(MergeSide::Left, b"left", vec![parse_fixture(LEFT, RowKeyKind::Explicit)]);
    source.add(MergeSide::Right, b"right", vec![parse_fixture(CONFLICT, RowKeyKind::Explicit)]);
    let base = snapshot(base_schema, manifest(1, 1, b"base"), Some(base_checkpoint));
    let left = snapshot(left_schema, manifest(2, 2, b"left"), Some(left_checkpoint));
    let right = snapshot(right_schema, manifest(3, 3, b"right"), Some(right_checkpoint));
    (base, left, right, source)
}

#[test]
fn independent_edits_to_one_keyed_row_merge_by_field_from_orna_fixtures() {
    let base_row = parse_fixture(BASE, RowKeyKind::Explicit);
    let left_row = parse_fixture(LEFT, RowKeyKind::Explicit);
    let right_row = parse_fixture(RIGHT, RowKeyKind::Explicit);
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"base", vec![base_row]);
    source.add(MergeSide::Left, b"left", vec![left_row]);
    source.add(MergeSide::Right, b"right", vec![right_row]);
    let base = snapshot(schema(true, FieldType::Str), manifest(1, 1, b"base"), None);
    let left = snapshot(schema(true, FieldType::Str), manifest(2, 2, b"left"), None);
    let right = snapshot(schema(true, FieldType::Str), manifest(3, 3, b"right"), None);

    let plan = merge_three_way_snapshots(&base, &left, &right, &mut source, budget()).unwrap();
    let MergedSegment::Rows { rows, .. } = &plan.tables[&id(1)].segments[0] else { panic!("changed range is rebuilt") };
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].fields[&id(2)], string("Grace"));
    assert_eq!(rows[0].fields[&id(3)], string("Paris"));
}

#[test]
fn same_field_conflict_is_reported_without_returning_a_partial_plan() {
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"base", vec![parse_fixture(BASE, RowKeyKind::Explicit)]);
    source.add(MergeSide::Left, b"left", vec![parse_fixture(LEFT, RowKeyKind::Explicit)]);
    source.add(MergeSide::Right, b"right", vec![parse_fixture(CONFLICT, RowKeyKind::Explicit)]);
    let base = snapshot(schema(true, FieldType::Str), manifest(1, 1, b"base"), None);
    let left = snapshot(schema(true, FieldType::Str), manifest(2, 2, b"left"), None);
    let right = snapshot(schema(true, FieldType::Str), manifest(3, 3, b"right"), None);

    let error = merge_three_way_snapshots(&base, &left, &right, &mut source, budget()).unwrap_err();
    let BranchMergeError::Conflicts { conflicts, report } = error else { panic!("bounded semantic conflict") };
    assert!(matches!(conflicts.as_slice(), [BranchMergeConflict::Row { .. }]));
    assert_eq!(report.conflicts_lower_bound, 1);
    assert!(report.affected_ranges.contains(&(id(1), KeyRange::all())));
}

#[test]
fn equal_segment_digest_skips_unchanged_range_before_row_decode() {
    let row = parse_fixture(BASE, RowKeyKind::Explicit);
    let key = row.key.encode().unwrap();
    let low = RowSegmentManifest { locator: b"low".to_vec(), range: KeyRange::new(None, Some(key.clone())).unwrap(), digest: [7; 32] };
    let changed_base = RowSegmentManifest { locator: b"base-high".to_vec(), range: KeyRange::new(Some(key.clone()), None).unwrap(), digest: [1; 32] };
    let changed_left = RowSegmentManifest { locator: b"left-high".to_vec(), digest: [2; 32], ..changed_base.clone() };
    let changed_right = RowSegmentManifest { locator: b"right-high".to_vec(), digest: [3; 32], ..changed_base.clone() };
    let table_manifest = |digest, high| TableManifest { digest: [digest; 32], segments: vec![low.clone(), high] };
    let base = snapshot(schema(true, FieldType::Str), table_manifest(10, changed_base), None);
    let left = snapshot(schema(true, FieldType::Str), table_manifest(11, changed_left), None);
    let right = snapshot(schema(true, FieldType::Str), table_manifest(12, changed_right), None);
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"base-high", vec![row.clone()]);
    source.add(MergeSide::Left, b"left-high", vec![parse_fixture(LEFT, RowKeyKind::Explicit)]);
    source.add(MergeSide::Right, b"right-high", vec![parse_fixture(RIGHT, RowKeyKind::Explicit)]);

    let plan = merge_three_way_snapshots(&base, &left, &right, &mut source, budget()).unwrap();
    assert_eq!(source.visited.len(), 3, "the equal low segment must not be decoded");
    assert!(source.visited.iter().all(|(_, locator)| locator.ends_with(b"high")));
    assert!(matches!(plan.tables[&id(1)].segments[0], MergedSegment::Reuse { from: MergeSide::Left, .. }));
}

