#[test]
fn unavailable_or_pruned_rows_fail_closed_instead_of_becoming_deletes() {
    struct UnavailableRows;
    impl BranchRowSource for UnavailableRows {
        fn visit_rows(
            &mut self,
            _side: MergeSide,
            _table: ObjectId,
            _segment: Option<&RowSegmentManifest>,
            _range: &KeyRange,
            _visitor: &mut dyn FnMut(KeyedRow) -> bool,
        ) -> Result<(), String> {
            Err("segment is pruned or unavailable".into())
        }
    }

    let base = snapshot(schema(true, FieldType::Str), manifest(1, 1, b"base"), None);
    let left = snapshot(schema(true, FieldType::Str), manifest(2, 2, b"left"), None);
    let right = snapshot(schema(true, FieldType::Str), manifest(3, 3, b"right"), None);
    let error = merge_three_way_snapshots(&base, &left, &right, &mut UnavailableRows, budget())
        .unwrap_err();
    assert_eq!(
        error,
        BranchMergeError::RowRead {
            message: "segment is pruned or unavailable".into(),
        }
    );
}

#[test]
fn nested_checkpoint_reset_extensions_merge_as_independent_fixture_states() {
    let root_id = b"consumer/reset-root".to_vec();
    let child_id = [root_id.as_slice(), b"/child".as_slice()].concat();
    let leaf_id = [child_id.as_slice(), b"/leaf".as_slice()].concat();
    let sibling_id = [root_id.as_slice(), b"-sibling".as_slice()].concat();
    let created_id = [leaf_id.as_slice(), b"/new".as_slice()].concat();
    let base_state = parse_checkpoint_fixture(CHECKPOINT_BASE);
    let reset_state = parse_checkpoint_fixture(CHECKPOINT_RESET);

    // Checkpoint identities are exact stable keys. A slash-shaped extension
    // has no cascading reset semantics; equal reset fixtures coalesce, and
    // independent one-sided resets compose regardless of branch orientation.
    for root_reset_left in [true, false] {
        let mut base = snapshot(
            schema(true, FieldType::Str),
            manifest(1, 1, b"same"),
            None,
        );
        let mut left = snapshot(
            schema(true, FieldType::Str),
            manifest(1, 1, b"same"),
            None,
        );
        let mut right = snapshot(
            schema(true, FieldType::Str),
            manifest(1, 1, b"same"),
            None,
        );

        for checkpoint_id in [&root_id, &child_id, &leaf_id, &sibling_id] {
            base.checkpoints.insert(checkpoint_id.clone(), base_state.clone());
            left.checkpoints.insert(checkpoint_id.clone(), base_state.clone());
            right.checkpoints.insert(checkpoint_id.clone(), base_state.clone());
        }

        if root_reset_left {
            left.checkpoints.insert(root_id.clone(), reset_state.clone());
            right.checkpoints.insert(leaf_id.clone(), reset_state.clone());
            left.checkpoints.insert(created_id.clone(), reset_state.clone());
        } else {
            right.checkpoints.insert(root_id.clone(), reset_state.clone());
            left.checkpoints.insert(leaf_id.clone(), reset_state.clone());
            right.checkpoints.insert(created_id.clone(), reset_state.clone());
        }
        left.checkpoints.insert(child_id.clone(), reset_state.clone());
        right.checkpoints.insert(child_id.clone(), reset_state.clone());

        let mut source = FixtureRows::default();
        let plan = merge_three_way_snapshots(&base, &left, &right, &mut source, budget()).unwrap();

        assert_eq!(plan.report.conflicts_lower_bound, 0);
        assert!(source.visited.is_empty());
        assert_eq!(plan.checkpoints.len(), 5);
        for checkpoint_id in [&root_id, &child_id, &leaf_id, &created_id] {
            assert_eq!(plan.checkpoints[checkpoint_id.as_slice()], reset_state);
        }
        assert_eq!(plan.checkpoints[sibling_id.as_slice()], base_state);
    }
}

#[test]
fn nested_checkpoint_reset_conflicts_preserve_fixture_states_and_identity() {
    let checkpoint_id = b"consumer/reset/root/child/leaf/tail".to_vec();
    let base_state = parse_checkpoint_fixture(CHECKPOINT_BASE);
    let reset_state = parse_checkpoint_fixture(CHECKPOINT_RESET);
    let advance_state = parse_checkpoint_fixture(CHECKPOINT_EDITED);

    // Reset-to-no-position is still a present checkpoint. Against a deletion
    // or an independently advanced position, it conflicts with the full
    // fixture states intact, whichever side contains the reset.
    for reset_left in [true, false] {
        for conflict_with_delete in [true, false] {
            let other_state = if conflict_with_delete {
                None
            } else {
                Some(advance_state.clone())
            };
            let (left_state, right_state) = if reset_left {
                (Some(reset_state.clone()), other_state)
            } else {
                (other_state, Some(reset_state.clone()))
            };

            let mut base = snapshot(
                schema(true, FieldType::Str),
                manifest(1, 1, b"same"),
                None,
            );
            let mut left = snapshot(
                schema(true, FieldType::Str),
                manifest(1, 1, b"same"),
                None,
            );
            let mut right = snapshot(
                schema(true, FieldType::Str),
                manifest(1, 1, b"same"),
                None,
            );
            base.checkpoints.insert(checkpoint_id.clone(), base_state.clone());
            if let Some(state) = left_state.as_ref() {
                left.checkpoints.insert(checkpoint_id.clone(), state.clone());
            }
            if let Some(state) = right_state.as_ref() {
                right.checkpoints.insert(checkpoint_id.clone(), state.clone());
            }

            let mut source = FixtureRows::default();
            let error = merge_three_way_snapshots(&base, &left, &right, &mut source, budget())
                .unwrap_err();
            let BranchMergeError::Conflicts { conflicts, report } = error else {
                panic!("nested reset diverging from deletion or advance remains unresolved")
            };
            assert_eq!(
                conflicts,
                vec![BranchMergeConflict::CheckpointConflict {
                    id: checkpoint_id.clone(),
                    conflict: orna_evolution_v1::CheckpointMergeConflict {
                        base: Some(base_state.clone()),
                        left: left_state,
                        right: right_state,
                    },
                }]
            );
            assert_eq!(report.conflicts_lower_bound, 1);
            assert_eq!(report.affected_checkpoints.len(), 1);
            assert!(report.affected_checkpoints.contains(checkpoint_id.as_slice()));
            assert!(source.visited.is_empty());
        }
    }
}

#[test]
fn fixture_row_tombstones_are_exact_keys_and_follow_logical_depth_order() {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let middle = rekey_row(&shallow, "root/child");
    let short_sibling = rekey_row(&shallow, "z");
    let boundary = short_sibling.key.encode().unwrap();
    let shallow_range = KeyRange::new(None, Some(boundary.clone()))
        .expect("logical path keys sort before the short sibling despite encoded length");
    let sibling_range = KeyRange::new(Some(boundary), None).unwrap();
    let split_manifest = |digest, shallow_digest, sibling_digest, shallow_locator: &[u8], sibling_locator: &[u8]| {
        TableManifest {
            digest: [digest; 32],
            segments: vec![
                RowSegmentManifest {
                    locator: shallow_locator.to_vec(),
                    range: shallow_range.clone(),
                    digest: [shallow_digest; 32],
                },
                RowSegmentManifest {
                    locator: sibling_locator.to_vec(),
                    range: sibling_range.clone(),
                    digest: [sibling_digest; 32],
                },
            ],
        }
    };

    // The left side retains only the middle child; the right side retains
    // only the deepest child. Deleting a path-shaped key never cascades into
    // another depth, and the short sibling forces encoded and logical order
    // to differ because its CBOR text-length prefix is smaller.
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"depth-base-shallow", vec![shallow.clone(), middle.clone(), deep.clone()]);
    source.add(MergeSide::Base, b"depth-base-sibling", vec![short_sibling.clone()]);
    source.add(MergeSide::Left, b"depth-left-shallow", vec![middle]);
    source.add(MergeSide::Left, b"depth-left-sibling", vec![short_sibling.clone()]);
    source.add(MergeSide::Right, b"depth-right-shallow", vec![deep]);
    source.add(MergeSide::Right, b"depth-right-sibling", vec![short_sibling.clone()]);
    let base = snapshot(
        string_key_schema(),
        split_manifest(1, 1, 2, b"depth-base-shallow", b"depth-base-sibling"),
        None,
    );
    let left = snapshot(
        string_key_schema(),
        split_manifest(2, 3, 4, b"depth-left-shallow", b"depth-left-sibling"),
        None,
    );
    let right = snapshot(
        string_key_schema(),
        split_manifest(3, 5, 6, b"depth-right-shallow", b"depth-right-sibling"),
        None,
    );

    let plan = merge_three_way_snapshots(&base, &left, &right, &mut source, budget())
        .expect("independent nested keys merge as exact tombstones");
    let MergedSegment::Rows { rows, tombstones, .. } = &plan.tables[&id(1)].segments[0] else {
        panic!("changed fixture range materializes rows and tombstones")
    };
    assert!(rows.is_empty());
    assert_eq!(
        tombstones,
        &[string("root"), string("root/child"), string("root/child/deep")],
        "logical primary-key order keeps each ancestor before its deeper keys",
    );
    let MergedSegment::Rows { rows, tombstones, .. } = &plan.tables[&id(1)].segments[1] else {
        panic!("the short sibling range remains a separate merged range")
    };
    assert_eq!(rows, &[short_sibling]);
    assert!(tombstones.is_empty());
}

#[test]
fn fixture_nested_delete_edit_conflicts_follow_logical_key_order() {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let middle = rekey_row(&shallow, "root/child");
    let short_sibling = rekey_row(&shallow, "z");
    let base_rows = vec![shallow.clone(), middle.clone(), deep.clone(), short_sibling.clone()];
    let edited_rows = vec![
        edit_name(&shallow, "edited"),
        edit_name(&middle, "edited"),
        edit_name(&deep, "edited"),
        short_sibling.clone(),
    ];

    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"conflict-depth-base", base_rows);
    source.add(MergeSide::Left, b"conflict-depth-left", vec![short_sibling]);
    source.add(MergeSide::Right, b"conflict-depth-right", edited_rows);
    let base = snapshot(string_key_schema(), manifest(4, 4, b"conflict-depth-base"), None);
    let left = snapshot(string_key_schema(), manifest(5, 5, b"conflict-depth-left"), None);
    let right = snapshot(string_key_schema(), manifest(6, 6, b"conflict-depth-right"), None);

    let BranchMergeError::Conflicts { conflicts, report } =
        merge_three_way_snapshots(&base, &left, &right, &mut source, budget()).unwrap_err()
    else {
        panic!("nested delete/edit conflicts reject the complete plan")
    };
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| match conflict {
            BranchMergeConflict::Row {
                conflict: orna_evolution_v1::RowMergeConflict::DeleteAndEdit { key, .. },
                ..
            } => key.clone(),
            other => panic!("unexpected nested-key conflict: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(
        conflict_keys,
        vec![string("root"), string("root/child"), string("root/child/deep")],
    );
    assert_eq!(report.conflicts_lower_bound, 3);
    assert!(report.affected_ranges.contains(&(id(1), KeyRange::all())));
}

#[test]
fn fixture_depth_split_tombstones_follow_table_wide_primary_key_order() {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let middle = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);

    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"split-base-shallow", vec![shallow.clone()]);
    source.add(MergeSide::Base, b"split-base-middle", vec![middle.clone()]);
    source.add(MergeSide::Base, b"split-base-deep", vec![deep.clone()]);
    source.add(MergeSide::Left, b"split-left-shallow", Vec::new());
    source.add(MergeSide::Left, b"split-left-middle", vec![middle]);
    source.add(MergeSide::Left, b"split-left-deep", Vec::new());
    source.add(MergeSide::Right, b"split-right-shallow", Vec::new());
    source.add(MergeSide::Right, b"split-right-middle", Vec::new());
    source.add(MergeSide::Right, b"split-right-deep", vec![deep]);

    let base = snapshot(
        string_key_schema(),
        depth_split_manifest(1, [1, 2, 3], [b"split-base-shallow", b"split-base-middle", b"split-base-deep"]),
        None,
    );
    let left = snapshot(
        string_key_schema(),
        depth_split_manifest(2, [4, 5, 6], [b"split-left-shallow", b"split-left-middle", b"split-left-deep"]),
        None,
    );
    let right = snapshot(
        string_key_schema(),
        depth_split_manifest(3, [7, 8, 9], [b"split-right-shallow", b"split-right-middle", b"split-right-deep"]),
        None,
    );

    let plan = merge_three_way_snapshots(&base, &left, &right, &mut source, budget())
        .expect("depth-separated deletes resolve as exact tombstones");
    let segments = &plan.tables[&id(1)].segments;
    assert_eq!(segments.len(), 3);
    let ordered_tombstones = segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { rows, tombstones, .. } => {
                assert!(rows.is_empty());
                tombstones.clone()
            }
            other => panic!("each changed depth range materializes: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(
        ordered_tombstones,
        vec![string("root"), string("root/child"), string("root/child/deep")],
        "walking materialized segments preserves table-wide key order across depth boundaries",
    );
    assert_eq!(plan.report.rows_examined, 5);
    assert_eq!(source.visited.len(), 9);
}

fn cross_depth_load_inputs() -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let middle = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let mut source = FixtureRows::default();
    // Physical visitation is deepest-first. The completed logical result
    // must not inherit the row source's load order.
    source.add(
        MergeSide::Base,
        b"load-base",
        vec![deep.clone(), middle.clone(), shallow],
    );
    source.add(MergeSide::Left, b"load-left", vec![middle]);
    source.add(MergeSide::Right, b"load-right", vec![deep]);
    let base = snapshot(string_key_schema(), manifest(1, 1, b"load-base"), None);
    let left = snapshot(string_key_schema(), manifest(2, 2, b"load-left"), None);
    let right = snapshot(string_key_schema(), manifest(3, 3, b"load-right"), None);
    (base, left, right, source)
}

fn split_cross_depth_load_inputs(
    middle_on_left: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let shallow = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let middle = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"split-load-base-root", vec![shallow]);
    source.add(
        MergeSide::Base,
        b"split-load-base-middle",
        vec![middle.clone()],
    );
    source.add(MergeSide::Base, b"split-load-base-deep", vec![deep.clone()]);
    let (left_middle, left_deep, right_middle, right_deep) = if middle_on_left {
        (vec![middle], Vec::new(), Vec::new(), vec![deep])
    } else {
        (Vec::new(), vec![deep], vec![middle], Vec::new())
    };
    source.add(MergeSide::Left, b"split-load-left-root", Vec::new());
    source.add(MergeSide::Left, b"split-load-left-middle", left_middle);
    source.add(MergeSide::Left, b"split-load-left-deep", left_deep);
    source.add(MergeSide::Right, b"split-load-right-root", Vec::new());
    source.add(MergeSide::Right, b"split-load-right-middle", right_middle);
    source.add(MergeSide::Right, b"split-load-right-deep", right_deep);

    let base = snapshot(
        string_key_schema(),
        depth_split_manifest(
            21,
            [21, 22, 23],
            [
                b"split-load-base-root",
                b"split-load-base-middle",
                b"split-load-base-deep",
            ],
        ),
        None,
    );
    let left = snapshot(
        string_key_schema(),
        depth_split_manifest(
            24,
            [24, 25, 26],
            [
                b"split-load-left-root",
                b"split-load-left-middle",
                b"split-load-left-deep",
            ],
        ),
        None,
    );
    let right = snapshot(
        string_key_schema(),
        depth_split_manifest(
            27,
            [27, 28, 29],
            [
                b"split-load-right-root",
                b"split-load-right-middle",
                b"split-load-right-deep",
            ],
        ),
        None,
    );
    (base, left, right, source)
}

fn chain_split_manifest(
    digest: u8,
    segment_digest_start: u8,
    boundaries: &[Vec<u8>],
    locator_prefix: &str,
) -> (TableManifest, Vec<Vec<u8>>) {
    let mut segments = Vec::with_capacity(boundaries.len() + 1);
    let mut locators = Vec::with_capacity(boundaries.len() + 1);
    for index in 0..=boundaries.len() {
        let locator = format!("{locator_prefix}-{index}").into_bytes();
        locators.push(locator.clone());
        segments.push(RowSegmentManifest {
            locator,
            range: KeyRange::new(
                index.checked_sub(1).map(|previous| boundaries[previous].clone()),
                boundaries.get(index).cloned(),
            )
            .expect("fixture chain boundaries are in logical key order"),
            digest: [segment_digest_start + index as u8; 32],
        });
    }
    (TableManifest { digest: [digest; 32], segments }, locators)
}

fn tombstone_chain_load_inputs(
    split_layout: bool,
    left_keeps_even_chain_keys: bool,
    reverse_whole_loads: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let chain_rows = TOMBSTONE_CHAIN
        .split("\n\n")
        .map(|record| parse_fixture(record, RowKeyKind::Explicit))
        .collect::<Vec<_>>();
    assert_eq!(chain_rows.len(), 7);
    let sibling_index = chain_rows.len() - 1;
    let left_keeps = |index: usize| {
        index == sibling_index || (index % 2 == 0) == left_keeps_even_chain_keys
    };
    let right_keeps = |index: usize| index == sibling_index || !left_keeps(index);
    let mut source = FixtureRows::default();

    if split_layout {
        let boundaries = chain_rows
            .iter()
            .skip(1)
            .map(|row| row.key.encode().unwrap())
            .collect::<Vec<_>>();
        let (base_manifest, base_locators) = chain_split_manifest(31, 31, &boundaries, "chain-base");
        let (left_manifest, left_locators) = chain_split_manifest(32, 41, &boundaries, "chain-left");
        let (right_manifest, right_locators) = chain_split_manifest(33, 51, &boundaries, "chain-right");
        for (index, row) in chain_rows.iter().enumerate() {
            source.add(MergeSide::Base, &base_locators[index], vec![row.clone()]);
            source.add(
                MergeSide::Left,
                &left_locators[index],
                if left_keeps(index) { vec![row.clone()] } else { Vec::new() },
            );
            source.add(
                MergeSide::Right,
                &right_locators[index],
                if right_keeps(index) { vec![row.clone()] } else { Vec::new() },
            );
        }
        (
            snapshot(string_key_schema(), base_manifest, None),
            snapshot(string_key_schema(), left_manifest, None),
            snapshot(string_key_schema(), right_manifest, None),
            source,
        )
    } else {
        let mut base_rows = chain_rows.clone();
        let mut left_rows = chain_rows
            .iter()
            .enumerate()
            .filter(|(index, _)| left_keeps(*index))
            .map(|(_, row)| row.clone())
            .collect::<Vec<_>>();
        let mut right_rows = chain_rows
            .iter()
            .enumerate()
            .filter(|(index, _)| right_keeps(*index))
            .map(|(_, row)| row.clone())
            .collect::<Vec<_>>();
        if reverse_whole_loads {
            base_rows.reverse();
            left_rows.reverse();
            right_rows.reverse();
        }
        source.add(MergeSide::Base, b"chain-whole-base", base_rows);
        source.add(MergeSide::Left, b"chain-whole-left", left_rows);
        source.add(MergeSide::Right, b"chain-whole-right", right_rows);
        (
            snapshot(string_key_schema(), manifest(61, 61, b"chain-whole-base"), None),
            snapshot(string_key_schema(), manifest(62, 62, b"chain-whole-left"), None),
            snapshot(string_key_schema(), manifest(63, 63, b"chain-whole-right"), None),
            source,
        )
    }
}

fn paired_tombstone_chain_load_inputs(
    first_table_split: bool,
    first_left_keeps_even: bool,
    second_left_keeps_even: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let (mut base, mut left, mut right, mut source) =
        tombstone_chain_load_inputs(first_table_split, first_left_keeps_even, false);
    let (mut paired_base, mut paired_left, mut paired_right, paired_source) =
        tombstone_chain_load_inputs(!first_table_split, second_left_keeps_even, false);

    let mut second_table = paired_base.schema.tables[0].clone();
    second_table.id = id(2);
    second_table.name = "PairedContact".into();
    for snapshot in [&mut base, &mut left, &mut right] {
        snapshot.schema.tables.push(second_table.clone());
    }

    for (primary, paired) in [
        (&mut base, &mut paired_base),
        (&mut left, &mut paired_left),
        (&mut right, &mut paired_right),
    ] {
        let mut manifest = paired.tables.remove(&id(1)).expect("paired table manifest exists");
        for segment in &mut manifest.segments {
            let mut locator = b"paired-".to_vec();
            locator.extend_from_slice(&segment.locator);
            segment.locator = locator;
        }
        primary.tables.insert(id(2), manifest);
    }

    for ((side, locator), mut rows) in paired_source.rows {
        let mut paired_locator = b"paired-".to_vec();
        paired_locator.extend_from_slice(&locator);
        for row in &mut rows {
            row.table = id(2);
        }
        source.rows.insert((side, paired_locator), rows);
    }

    (base, left, right, source)
}

fn paired_tombstone_storm_inputs(
    layout: usize,
    reverse_rows: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let template = parse_fixture(TOMBSTONE_RECOVERY_STORM, RowKeyKind::Explicit);
    let make_rows = |table| {
        TOMBSTONE_STORM_KEYS
            .iter()
            .map(|key| {
                let mut row = rekey_row(&template, key);
                row.table = table;
                row
            })
            .collect::<Vec<_>>()
    };
    let table_one_rows = make_rows(id(1));
    let table_two_rows = make_rows(id(2));
    let (table_one_bounds, table_two_bounds): (&[&str], &[&str]) = if layout % 2 == 0 {
        (
            &["root/child", "root/child/deep", "root/child/deep/storm/c", "z"],
            &["root/child/deep", "root/child/deep/storm/e"],
        )
    } else {
        (
            &["root", "root/child/deep/storm/d"],
            &["root/child", "root/child/deep", "root/child/deep/storm/f"],
        )
    };

    let mut base_tables = BTreeMap::new();
    let mut left_tables = BTreeMap::new();
    let mut right_tables = BTreeMap::new();
    let mut source = FixtureRows::default();
    for (table, rows, boundaries, locator_prefix, digest) in [
        (id(1), table_one_rows, table_one_bounds, "paired-storm-a", 101_u8),
        (id(2), table_two_rows, table_two_bounds, "paired-storm-b", 131_u8),
    ] {
        let encoded_boundaries = boundaries
            .iter()
            .map(|boundary| string(boundary).encode().unwrap())
            .collect::<Vec<_>>();
        let (base_manifest, base_locators) =
            chain_split_manifest(digest, digest, &encoded_boundaries, &format!("{locator_prefix}-base"));
        let (left_manifest, left_locators) = chain_split_manifest(
            digest + 1,
            digest + 16,
            &encoded_boundaries,
            &format!("{locator_prefix}-left"),
        );
        let (right_manifest, right_locators) = chain_split_manifest(
            digest + 2,
            digest + 32,
            &encoded_boundaries,
            &format!("{locator_prefix}-right"),
        );

        for index in 0..base_manifest.segments.len() {
            let range = &base_manifest.segments[index].range;
            let rows_in_range = rows
                .iter()
                .filter(|row| range.contains(&row.key.encode().unwrap()))
                .cloned()
                .collect::<Vec<_>>();
            source.add(MergeSide::Base, &base_locators[index], rows_in_range);
            source.add(MergeSide::Left, &left_locators[index], Vec::new());
            source.add(MergeSide::Right, &right_locators[index], Vec::new());
        }
        base_tables.insert(table, base_manifest);
        left_tables.insert(table, left_manifest);
        right_tables.insert(table, right_manifest);
    }
    if reverse_rows {
        for rows in source.rows.values_mut() {
            rows.reverse();
        }
    }

    let schema = paired_depth_schema();
    let base = ThreeWaySnapshot { schema: schema.clone(), tables: base_tables, checkpoints: BTreeMap::new() };
    let left = ThreeWaySnapshot { schema: schema.clone(), tables: left_tables, checkpoints: BTreeMap::new() };
    let right = ThreeWaySnapshot { schema, tables: right_tables, checkpoints: BTreeMap::new() };
    (base, left, right, source)
}

fn paired_chained_storm_inputs(
    base_rows: &[KeyedRow],
    left_deleted: &[&str],
    right_deleted: &[&str],
    layout: usize,
    reverse_rows: bool,
    locator_prefix: &str,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    paired_chained_storm_inputs_by_table(
        &[base_rows, base_rows],
        left_deleted,
        right_deleted,
        layout,
        reverse_rows,
        locator_prefix,
    )
}

fn paired_chained_storm_inputs_by_table(
    base_rows_by_table: &[&[KeyedRow]; 2],
    left_deleted: &[&str],
    right_deleted: &[&str],
    layout: usize,
    reverse_rows: bool,
    locator_prefix: &str,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let mut base_tables = BTreeMap::new();
    let mut left_tables = BTreeMap::new();
    let mut right_tables = BTreeMap::new();
    let mut source = FixtureRows::default();
    for (table_index, table) in [id(1), id(2)].into_iter().enumerate() {
        let mut table_rows = base_rows_by_table[table_index].to_vec();
        for row in &mut table_rows {
            row.table = table;
        }
        let left_rows = table_rows
            .iter()
            .filter(|row| !left_deleted.iter().any(|key| row.key == string(key)))
            .cloned()
            .collect::<Vec<_>>();
        let right_rows = table_rows
            .iter()
            .filter(|row| !right_deleted.iter().any(|key| row.key == string(key)))
            .cloned()
            .collect::<Vec<_>>();
        let boundaries: &[&str] = if (layout + table_index) % 2 == 0 {
            &["root/child", "root/child/deep/leaf/twig", "z"]
        } else {
            &["root/child/deep", "root/child/deep/leaf/twig/bud", "z"]
        };
        let encoded_boundaries = boundaries
            .iter()
            .map(|boundary| string(boundary).encode().unwrap())
            .collect::<Vec<_>>();
        let prefix = format!("{locator_prefix}-table-{table_index}");
        let (base_manifest, base_locators) = chain_split_manifest(
            171 + table_index as u8,
            181 + table_index as u8,
            &encoded_boundaries,
            &format!("{prefix}-base"),
        );
        let (left_manifest, left_locators) = chain_split_manifest(
            191 + table_index as u8,
            201 + table_index as u8,
            &encoded_boundaries,
            &format!("{prefix}-left"),
        );
        let (right_manifest, right_locators) = chain_split_manifest(
            211 + table_index as u8,
            221 + table_index as u8,
            &encoded_boundaries,
            &format!("{prefix}-right"),
        );

        for (side, manifest, locators, rows) in [
            (MergeSide::Base, &base_manifest, &base_locators, &table_rows),
            (MergeSide::Left, &left_manifest, &left_locators, &left_rows),
            (
                MergeSide::Right,
                &right_manifest,
                &right_locators,
                &right_rows,
            ),
        ] {
            for (segment, locator) in manifest.segments.iter().zip(locators) {
                let mut rows_in_range = rows
                    .iter()
                    .filter(|row| segment.range.contains(&row.key.encode().unwrap()))
                    .cloned()
                    .collect::<Vec<_>>();
                if reverse_rows {
                    rows_in_range.reverse();
                }
                source.add(side, locator, rows_in_range);
            }
        }
        base_tables.insert(table, base_manifest);
        left_tables.insert(table, left_manifest);
        right_tables.insert(table, right_manifest);
    }

    let schema = paired_depth_schema();
    let base = ThreeWaySnapshot {
        schema: schema.clone(),
        tables: base_tables,
        checkpoints: BTreeMap::new(),
    };
    let left = ThreeWaySnapshot {
        schema: schema.clone(),
        tables: left_tables,
        checkpoints: BTreeMap::new(),
    };
    let right = ThreeWaySnapshot {
        schema,
        tables: right_tables,
        checkpoints: BTreeMap::new(),
    };
    (base, left, right, source)
}

fn add_chained_storm_fixture_rows(
    snapshot: &ThreeWaySnapshot,
    source: &mut FixtureRows,
    side: MergeSide,
    table: ObjectId,
    rows: &[KeyedRow],
) {
    let manifest = snapshot.tables.get(&table).expect("paired table manifest exists");
    for row in rows {
        let mut row = row.clone();
        row.table = table;
        let encoded_key = row.key.encode().expect("fixture keys remain encodable");
        let segment = manifest
            .segments
            .iter()
            .find(|segment| segment.range.contains(&encoded_key))
            .expect("the fixture key belongs to a paired depth range");
        source
            .rows
            .entry((side, segment.locator.clone()))
            .or_default()
            .push(row);
    }
}

fn paired_distinct_depth_chain_inputs(
    first_table_split: bool,
    first_left_keeps_even: bool,
    second_left_keeps_even: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let (mut base, mut left, mut right, mut source) = paired_tombstone_chain_load_inputs(
        first_table_split,
        first_left_keeps_even,
        second_left_keeps_even,
    );
    let mut second_rows = TOMBSTONE_PAIRED_CHAIN
        .split("\n\n")
        .map(|record| parse_fixture(record, RowKeyKind::Explicit))
        .collect::<Vec<_>>();
    assert_eq!(second_rows.len(), 7);
    for row in &mut second_rows {
        row.table = id(2);
    }

    let second_table_split = !first_table_split;
    let boundaries = second_rows
        .iter()
        .skip(1)
        .map(|row| row.key.encode().unwrap())
        .collect::<Vec<_>>();
    for snapshot in [&mut base, &mut left, &mut right] {
        let manifest = snapshot.tables.get_mut(&id(2)).expect("second table manifest exists");
        if second_table_split {
            assert_eq!(manifest.segments.len(), second_rows.len());
            for (index, segment) in manifest.segments.iter_mut().enumerate() {
                segment.range = KeyRange::new(
                    index.checked_sub(1).map(|previous| boundaries[previous].clone()),
                    boundaries.get(index).cloned(),
                )
                .expect("paired fixture chain boundaries are in logical key order");
            }
        }
    }

    let keeps = |side: MergeSide, index: usize| match side {
        MergeSide::Base => true,
        MergeSide::Left => index >= 3 || (index % 2 == 0) == second_left_keeps_even,
        MergeSide::Right => index >= 3 || (index % 2 == 0) != second_left_keeps_even,
    };
    for (side, snapshot) in [
        (MergeSide::Base, &base),
        (MergeSide::Left, &left),
        (MergeSide::Right, &right),
    ] {
        let locators = snapshot.tables[&id(2)]
            .segments
            .iter()
            .map(|segment| segment.locator.clone())
            .collect::<Vec<_>>();
        if second_table_split {
            for (index, locator) in locators.into_iter().enumerate() {
                source.rows.insert(
                    (side, locator),
                    if keeps(side, index) { vec![second_rows[index].clone()] } else { Vec::new() },
                );
            }
        } else {
            let rows = second_rows
                .iter()
                .enumerate()
                .filter(|(index, _)| keeps(side, *index))
                .map(|(_, row)| row.clone())
                .collect();
            source.rows.insert((side, locators[0].clone()), rows);
        }
    }

    (base, left, right, source)
}

fn flattened_row_tombstones(plan: &BranchMergePlan) -> Vec<CanonicalValue> {
    plan.tables[&id(1)]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { tombstones, .. } => tombstones.clone(),
            other => panic!("expected materialized cross-depth rows, got {other:?}"),
        })
        .collect()
}

fn flattened_live_row_keys(plan: &BranchMergePlan) -> Vec<CanonicalValue> {
    plan.tables[&id(1)]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { rows, .. } => rows
                .iter()
                .map(|row| row.key.clone())
                .collect::<Vec<_>>(),
            other => panic!("expected materialized chain rows, got {other:?}"),
        })
        .collect()
}

fn table_row_tombstones(plan: &BranchMergePlan, table: ObjectId) -> Vec<CanonicalValue> {
    let mut tombstones = Vec::new();
    for segment in &plan.tables[&table].segments {
        if let MergedSegment::Rows { tombstones: segment_tombstones, .. } = segment {
            tombstones.extend(segment_tombstones.iter().cloned());
        }
    }
    tombstones
}

fn table_live_row_keys(plan: &BranchMergePlan, table: ObjectId) -> Vec<CanonicalValue> {
    plan.tables[&table]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { rows, .. } => rows.iter().map(|row| row.key.clone()).collect::<Vec<_>>(),
            other => panic!("expected materialized chain rows, got {other:?}"),
        })
        .collect()
}

fn table_live_rows(plan: &BranchMergePlan, table: ObjectId) -> Vec<KeyedRow> {
    plan.tables[&table]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { rows, .. } => rows.clone(),
            other => panic!("expected materialized chained rows, got {other:?}"),
        })
        .collect()
}

fn logical_split_manifest(digest: u8, boundaries: &[&str]) -> TableManifest {
    let encoded_boundaries = boundaries
        .iter()
        .map(|boundary| string(boundary).encode().unwrap())
        .collect::<Vec<_>>();
    let mut ranges = Vec::with_capacity(encoded_boundaries.len() + 1);
    let mut start = None;
    for end in encoded_boundaries {
        ranges.push(KeyRange::new(start, Some(end.clone())).unwrap());
        start = Some(end);
    }
    ranges.push(KeyRange::new(start, None).unwrap());
    TableManifest {
        digest: [digest; 32],
        segments: ranges
            .into_iter()
            .enumerate()
            .map(|(index, range)| RowSegmentManifest {
                locator: format!("layout-{digest}-{index}").into_bytes(),
                range,
                digest: [digest.wrapping_add(index as u8); 32],
            })
            .collect(),
    }
}

fn unaligned_tombstone_inputs(
    layout: u8,
    with_conflicts: bool,
    reverse_rows: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let root = parse_fixture(TOMBSTONE_DEPTH_SHALLOW, RowKeyKind::Explicit);
    let middle = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    let deep = parse_fixture(TOMBSTONE_DEPTH_DEEP, RowKeyKind::Explicit);
    let tail = rekey_row(&root, "z");
    let mut left_rows = if with_conflicts {
        vec![deep.clone(), edit_name(&tail, "left tail edit")]
    } else {
        vec![middle.clone(), tail.clone()]
    };
    let mut right_rows = if with_conflicts {
        vec![root.clone(), edit_name(&middle, "right middle edit")]
    } else {
        vec![deep.clone(), tail.clone()]
    };
    let mut base_rows = vec![root, middle, deep, tail];
    if reverse_rows {
        base_rows.reverse();
        left_rows.reverse();
        right_rows.reverse();
    }

    // Different split points force the planner's whole-table fallback. The
    // logical key order is root, child, deep child, then the short `z` key.
    let (base_bounds, left_bounds, right_bounds) = if layout == 0 {
        (&["root/child", "root/child/deep"][..], &["root/child/deep"][..], &[][..])
    } else {
        (&[][..], &["root/child", "root/child/deep"][..], &["root/child"][..])
    };
    let base = snapshot(
        string_key_schema(),
        logical_split_manifest(31 + layout * 3, base_bounds),
        None,
    );
    let left = snapshot(
        string_key_schema(),
        logical_split_manifest(32 + layout * 3, left_bounds),
        None,
    );
    let right = snapshot(
        string_key_schema(),
        logical_split_manifest(33 + layout * 3, right_bounds),
        None,
    );
    let mut source = FixtureRows::default();
    // An absent segment locator denotes the complete logical table for this
    // adapter fixture, as required by the row-source contract.
    source.add(MergeSide::Base, b"", base_rows);
    source.add(MergeSide::Left, b"", left_rows);
    source.add(MergeSide::Right, b"", right_rows);
    (base, left, right, source)
}

fn recovery_tombstone_storm_inputs(
    layout: u8,
    edit_right: bool,
    reverse_rows: bool,
) -> (
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    ThreeWaySnapshot,
    FixtureRows,
) {
    let template = parse_fixture(TOMBSTONE_RECOVERY_STORM, RowKeyKind::Explicit);
    let mut base_rows = TOMBSTONE_STORM_KEYS
        .iter()
        .map(|key| rekey_row(&template, key))
        .collect::<Vec<_>>();
    let mut left_rows = Vec::new();
    let mut right_rows = if edit_right {
        base_rows
            .iter()
            .enumerate()
            .map(|(index, row)| edit_name(row, &format!("right edit {index}")))
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    if reverse_rows {
        base_rows.reverse();
        left_rows.reverse();
        right_rows.reverse();
    }

    // Each layout uses different boundaries so recovery retries exercise the
    // complete-table fallback as well as different source visitation orders.
    let (base_bounds, left_bounds, right_bounds) = if layout == 0 {
        (&["root/child"][..], &[][..], &["root/child/deep"][..])
    } else {
        (&[][..], &["root/child/deep"][..], &["root/child"][..])
    };
    let base = snapshot(
        string_key_schema(),
        logical_split_manifest(81 + layout * 3, base_bounds),
        None,
    );
    let left = snapshot(
        string_key_schema(),
        logical_split_manifest(82 + layout * 3, left_bounds),
        None,
    );
    let right = snapshot(
        string_key_schema(),
        logical_split_manifest(83 + layout * 3, right_bounds),
        None,
    );
    let mut source = FixtureRows::default();
    source.add(MergeSide::Base, b"", base_rows);
    source.add(MergeSide::Left, b"", left_rows);
    source.add(MergeSide::Right, b"", right_rows);
    (base, left, right, source)
}

#[test]
fn concurrent_unaligned_split_tombstones_keep_logical_order() {
    let (base_a, left_a, right_a, source_a) = unaligned_tombstone_inputs(0, false, false);
    let (base_b, left_b, right_b, source_b) = unaligned_tombstone_inputs(1, false, true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let load_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        let plan = merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 0 },
        )
        .expect("the first unaligned split load completes");
        (plan, source.source.visited)
    });
    let load_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        let plan = merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 0 },
        )
        .expect("the second unaligned split load completes");
        (plan, source.source.visited)
    });

    let (plan_a, visits_a) = load_a.join().expect("first fallback worker completes");
    let (plan_b, visits_b) = load_b.join().expect("second fallback worker completes");
    assert_eq!(plan_a, plan_b, "layout and row-source order do not change the merge");
    assert_eq!(
        visits_a,
        vec![
            (MergeSide::Base, Vec::new()),
            (MergeSide::Left, Vec::new()),
            (MergeSide::Right, Vec::new()),
        ],
        "unaligned manifests are read once per side as complete tables",
    );
    assert_eq!(visits_b, visits_a);
    assert_eq!(plan_a.report.rows_examined, 8);
    let [MergedSegment::Rows { range, rows, tombstones }] =
        plan_a.tables[&id(1)].segments.as_slice()
    else {
        panic!("an unaligned table merge materializes one complete range")
    };
    assert_eq!(*range, KeyRange::all());
    assert_eq!(
        tombstones,
        &[string("root"), string("root/child"), string("root/child/deep")],
    );
    assert_eq!(rows.iter().map(|row| row.key.clone()).collect::<Vec<_>>(), vec![string("z")]);
}

#[test]
fn concurrent_unaligned_tombstones_and_conflicts_follow_one_logical_order() {
    let (base_a, left_a, right_a, source_a) = unaligned_tombstone_inputs(0, true, false);
    let (base_b, left_b, right_b, source_b) = unaligned_tombstone_inputs(1, true, true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let merge_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 2 },
        )
    });
    let merge_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 2 },
        )
    });
    let result_a = merge_a.join().expect("first conflict worker completes");
    let result_b = merge_b.join().expect("second conflict worker completes");
    assert_eq!(result_a, result_b, "concurrent fallback plans report the same conflict order");
    let BranchMergeError::Conflicts { conflicts, report } = result_a.unwrap_err() else {
        panic!("both ordered delete/edit conflicts fit the exact budget")
    };
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| match conflict {
            BranchMergeConflict::Row {
                conflict: orna_evolution_v1::RowMergeConflict::DeleteAndEdit { key, .. },
                ..
            } => key.clone(),
            other => panic!("unexpected unaligned split conflict: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(conflict_keys, vec![string("root/child"), string("z")]);
    assert_eq!(report.rows_examined, 8);
    assert_eq!(report.conflicts_lower_bound, 2);
    assert_eq!(report.affected_ranges, [(id(1), KeyRange::all())].into_iter().collect());

    for (max_conflicts, lower_bound) in [(0, 1), (1, 2)] {
        let (base, left, right, mut source) = unaligned_tombstone_inputs(0, true, true);
        let error = merge_three_way_snapshots(
            &base,
            &left,
            &right,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts },
        )
        .unwrap_err();
        let BranchMergeError::BudgetExceeded { report } = error else {
            panic!("the first conflict beyond the detail budget stops the fallback walk")
        };
        assert_eq!(report.rows_examined, 8);
        assert_eq!(report.conflicts_lower_bound, lower_bound);
        assert_eq!(report.affected_ranges, [(id(1), KeyRange::all())].into_iter().collect());
    }
}

#[test]
fn concurrent_recovery_retries_preserve_tombstone_conflict_order() {
    // The reference requires an unavailable row history to fail closed but is
    // silent on retry scheduling. After row recovery, fresh plans restart from
    // canonical range/key order and must not inherit partial work from the
    // failed attempt.
    let (base, left, right, source) = unaligned_tombstone_inputs(0, true, false);
    let mut interrupted = RecoveringFixtureRows {
        source,
        fail_first_load: true,
    };
    let error = merge_three_way_snapshots(
        &base,
        &left,
        &right,
        &mut interrupted,
        BranchMergeBudget { max_rows_examined: 8, max_conflicts: 2 },
    )
    .unwrap_err();
    assert_eq!(
        error,
        BranchMergeError::RowRead {
            message: "fixture row source stopped at recovery boundary".into(),
        },
    );
    assert!(interrupted.source.visited.is_empty(), "the failed source yielded no partial rows");

    let (base_a, left_a, right_a, source_a) = unaligned_tombstone_inputs(0, true, false);
    let (base_b, left_b, right_b, source_b) = unaligned_tombstone_inputs(1, true, true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let retry_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 2 },
        )
    });
    let retry_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: 8, max_conflicts: 2 },
        )
    });
    let result_a = retry_a.join().expect("first recovered retry completes");
    let result_b = retry_b.join().expect("second recovered retry completes");
    assert_eq!(result_a, result_b, "recovery and concurrent scheduling preserve the same result");
    let BranchMergeError::Conflicts { conflicts, report } = result_a.unwrap_err() else {
        panic!("recovered row history retains its ordered delete/edit conflicts")
    };
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| match conflict {
            BranchMergeConflict::Row {
                conflict: orna_evolution_v1::RowMergeConflict::DeleteAndEdit { key, .. },
                ..
            } => key.clone(),
            other => panic!("unexpected recovered merge conflict: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(conflict_keys, vec![string("root/child"), string("z")]);
    assert_eq!(report.rows_examined, 8);
    assert_eq!(report.conflicts_lower_bound, 2);
    assert_eq!(report.affected_ranges, [(id(1), KeyRange::all())].into_iter().collect());
}

#[test]
fn concurrent_recovery_tombstone_storms_keep_canonical_key_order() {
    // MERGE-005 bounds work but does not prescribe output ordering after a
    // partial row-source recovery. Fresh retries use canonical key order.
    let row_budget = TOMBSTONE_STORM_KEYS.len();
    let (base, left, right, source) = recovery_tombstone_storm_inputs(0, false, false);
    let mut interrupted = PartialRecoveringFixtureRows {
        source,
        fail_after_rows: Some(4),
        rows_delivered_before_failure: 0,
    };
    assert_eq!(
        merge_three_way_snapshots(
            &base,
            &left,
            &right,
            &mut interrupted,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: 0 },
        ),
        Err(BranchMergeError::RowRead {
            message: "fixture row source failed after partial storm delivery".into(),
        }),
    );
    assert_eq!(interrupted.rows_delivered_before_failure, 4);

    let (base_a, left_a, right_a, source_a) = recovery_tombstone_storm_inputs(0, false, false);
    let (base_b, left_b, right_b, source_b) = recovery_tombstone_storm_inputs(1, false, true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let retry_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: 0 },
        )
    });
    let retry_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: 0 },
        )
    });
    let plan_a = retry_a.join().expect("first storm retry completes").unwrap();
    let plan_b = retry_b.join().expect("second storm retry completes").unwrap();
    assert_eq!(plan_a, plan_b, "layout and concurrent row visitation do not reorder tombstones");
    let [MergedSegment::Rows { range, rows, tombstones }] =
        plan_a.tables[&id(1)].segments.as_slice()
    else {
        panic!("the recovered storm materializes one complete key range")
    };
    assert_eq!(*range, KeyRange::all());
    assert!(rows.is_empty());
    assert_eq!(
        tombstones,
        &TOMBSTONE_STORM_KEYS.iter().map(|key| string(key)).collect::<Vec<_>>(),
    );
    assert_eq!(plan_a.report.rows_examined, row_budget);
    assert_eq!(plan_a.report.conflicts_lower_bound, 0);
}

#[test]
fn paired_depth_recovery_retries_keep_table_and_tombstone_order() {
    // MERGE-1 requires a complete isolated result but leaves paired table and
    // depth-range ordering open. The v1 policy discards earlier tombstones
    // when a later pair range fails, then retries the ordered walk from its
    // first table after recovery.
    let (base, left, right, source) = paired_depth_recovery_inputs(false);
    let mut interrupted = FailAfterRowsFixtureRows {
        source,
        fail_after_rows: 6,
        rows_delivered: 0,
        failed_at: None,
    };
    assert_eq!(
        merge_three_way_snapshots(
            &base,
            &left,
            &right,
            &mut interrupted,
            BranchMergeBudget { max_rows_examined: 11, max_conflicts: 0 },
        ),
        Err(BranchMergeError::RowRead {
            message: "fixture row source failed after a partial row prefix".into(),
        }),
    );
    assert_eq!(interrupted.rows_delivered, 6);
    assert_eq!(
        interrupted.failed_at,
        Some((id(2), MergeSide::Base, b"pair-b-base-middle".to_vec())),
        "the first table completed before the paired table failed at its middle depth",
    );

    let (base_a, left_a, right_a, source_a) = paired_depth_recovery_inputs(false);
    let (base_b, left_b, right_b, source_b) = paired_depth_recovery_inputs(true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let retry_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows { source: source_a, first_load: Some(start_a) };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: 11, max_conflicts: 0 },
        )
    });
    let retry_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows { source: source_b, first_load: Some(start) };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: 11, max_conflicts: 0 },
        )
    });

    let plan_a = retry_a.join().expect("first paired-depth retry completes").unwrap();
    let plan_b = retry_b.join().expect("second paired-depth retry completes").unwrap();
    assert_eq!(plan_a, plan_b, "recovered paired depth merges ignore row visitation order");
    assert_eq!(plan_a.tables.keys().copied().collect::<Vec<_>>(), vec![id(1), id(2)]);
    assert_eq!(plan_a.report.rows_examined, 11);
    assert_eq!(plan_a.report.conflicts_lower_bound, 0);

    let table_one_tombstones = plan_a.tables[&id(1)]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { tombstones, .. } => tombstones.clone(),
            other => panic!("first paired depth range is materialized: {other:?}"),
        })
        .collect::<Vec<_>>();
    let table_two_tombstones = plan_a.tables[&id(2)]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { tombstones, .. } => tombstones.clone(),
            other => panic!("second paired depth range is materialized: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(
        table_one_tombstones,
        vec![string("root"), string("root/child"), string("root/child/deep")],
    );
    assert_eq!(table_two_tombstones, vec![string("root"), string("root/child/deep")]);
    let table_two_rows = plan_a.tables[&id(2)]
        .segments
        .iter()
        .flat_map(|segment| match segment {
            MergedSegment::Rows { rows, .. } => rows.clone(),
            other => panic!("second paired depth range is materialized: {other:?}"),
        })
        .collect::<Vec<_>>();
    let mut expected_table_two_row = parse_fixture(TOMBSTONE_DEPTH_MIDDLE, RowKeyKind::Explicit);
    expected_table_two_row.table = id(2);
    assert_eq!(table_two_rows, vec![expected_table_two_row]);
}

#[test]
fn concurrent_recovery_tombstone_conflict_storm_respects_the_detail_budget() {
    // A recovered conflict storm reports its full canonical sequence when it
    // fits; over budget, the first omitted conflict still advances the lower
    // bound and leaves the candidate unavailable.
    let row_budget = TOMBSTONE_STORM_KEYS.len() * 2;
    let conflict_budget = TOMBSTONE_STORM_KEYS.len();
    let (base, left, right, source) = recovery_tombstone_storm_inputs(0, true, false);
    let mut interrupted = PartialRecoveringFixtureRows {
        source,
        fail_after_rows: Some(4),
        rows_delivered_before_failure: 0,
    };
    assert!(matches!(
        merge_three_way_snapshots(
            &base,
            &left,
            &right,
            &mut interrupted,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: conflict_budget },
        ),
        Err(BranchMergeError::RowRead { .. }),
    ));
    assert_eq!(interrupted.rows_delivered_before_failure, 4);

    let (base_a, left_a, right_a, source_a) = recovery_tombstone_storm_inputs(0, true, false);
    let (base_b, left_b, right_b, source_b) = recovery_tombstone_storm_inputs(1, true, true);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let retry_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: conflict_budget },
        )
    });
    let retry_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: conflict_budget },
        )
    });
    let result_a = retry_a.join().expect("first conflict storm retry completes");
    let result_b = retry_b.join().expect("second conflict storm retry completes");
    assert_eq!(result_a, result_b, "recovery and source order preserve conflict diagnostics");
    let BranchMergeError::Conflicts { conflicts, report } = result_a.unwrap_err() else {
        panic!("the exact conflict detail budget retains the full storm")
    };
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| match conflict {
            BranchMergeConflict::Row {
                conflict: orna_evolution_v1::RowMergeConflict::DeleteAndEdit { key, .. },
                ..
            } => key.clone(),
            other => panic!("unexpected recovery storm conflict: {other:?}"),
        })
        .collect::<Vec<_>>();
    assert_eq!(
        conflict_keys,
        TOMBSTONE_STORM_KEYS.iter().map(|key| string(key)).collect::<Vec<_>>(),
    );
    assert_eq!(report.rows_examined, row_budget);
    assert_eq!(report.conflicts_lower_bound, conflict_budget);

    let (base, left, right, mut source) = recovery_tombstone_storm_inputs(1, true, true);
    let error = merge_three_way_snapshots(
        &base,
        &left,
        &right,
        &mut source,
        BranchMergeBudget { max_rows_examined: row_budget, max_conflicts: 3 },
    )
    .unwrap_err();
    let BranchMergeError::BudgetExceeded { report } = error else {
        panic!("the first storm conflict above budget stops planning")
    };
    assert_eq!(report.rows_examined, row_budget);
    assert_eq!(report.conflicts_lower_bound, 4);
    assert_eq!(report.affected_ranges, [(id(1), KeyRange::all())].into_iter().collect());
}

#[test]
fn fixture_cross_depth_tombstones_keep_order_at_exact_load_budget() {
    // ORNA-MERGE-005 requires bounded work and an isolated complete result,
    // but is silent on path-depth ordering. A complete load therefore emits
    // tombstones in canonical key order.
    let (base, left, right, mut source) = cross_depth_load_inputs();
    let plan = merge_three_way_snapshots(
        &base,
        &left,
        &right,
        &mut source,
        BranchMergeBudget { max_rows_examined: 5, max_conflicts: 0 },
    )
    .expect("the exact load budget produces a complete cross-depth merge");
    assert_eq!(plan.report.rows_examined, 5);
    let MergedSegment::Rows { rows, tombstones, .. } = &plan.tables[&id(1)].segments[0] else {
        panic!("cross-depth changes materialize as one bounded segment")
    };
    assert!(rows.is_empty());
    assert_eq!(
        tombstones,
        &[string("root"), string("root/child"), string("root/child/deep")],
        "load visitation order does not change canonical cross-depth tombstone order",
    );
}

#[test]
fn concurrent_split_loads_keep_tombstones_ordered_across_depth_boundaries() {
    // The reference defines bounded isolated merges but is silent on
    // concurrent load scheduling. Pin the local rule that each independent
    // result follows canonical key order across segment boundaries.
    let (base_a, left_a, right_a, source_a) = split_cross_depth_load_inputs(true);
    let (base_b, left_b, right_b, source_b) = split_cross_depth_load_inputs(false);
    let start = Arc::new(Barrier::new(2));
    let start_a = Arc::clone(&start);
    let load_a = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_a,
            first_load: Some(start_a),
        };
        merge_three_way_snapshots(
            &base_a,
            &left_a,
            &right_a,
            &mut source,
            BranchMergeBudget { max_rows_examined: 5, max_conflicts: 0 },
        )
        .expect("first split load completes")
    });
    let load_b = std::thread::spawn(move || {
        let mut source = BarrierFixtureRows {
            source: source_b,
            first_load: Some(start),
        };
        merge_three_way_snapshots(
            &base_b,
            &left_b,
            &right_b,
            &mut source,
            BranchMergeBudget { max_rows_examined: 5, max_conflicts: 0 },
        )
        .expect("opposite-orientation split load completes")
    });

    let plan_a = load_a.join().expect("first split worker completes");
    let plan_b = load_b.join().expect("second split worker completes");
    assert_eq!(plan_a, plan_b, "opposite tombstone orientations merge identically");
    assert_eq!(plan_a.report.rows_examined, 5);
    assert_eq!(
        flattened_row_tombstones(&plan_a),
        vec![string("root"), string("root/child"), string("root/child/deep")],
        "each segment boundary contributes tombstones in table-wide primary-key order",
    );
    assert_eq!(plan_a.tables[&id(1)].segments.len(), 3);
}

